// ProposalAction — Кнопка карточки: что отправить и чего ждать
type ProposalAction struct {
	// approve — «Записать и провести»; approve_draft — «Записать черновиком» (без проведения); reject — «Отклонить»
	Action ProposalActionAction `json:"action"`
	// Тело запроса действия. Значения в угловых скобках — подставить: idempotency_key — свой UUID (повторять тот же при повторе нажатия), reason — текст причины от человека
	Body map[string]any `json:"body"`
	// Почему кнопка выключена; есть только при enabled = false
	DisabledReason *string `json:"disabled_reason,omitempty"`
	// Что произойдёт по нажатию — текст для окна подтверждения
	Effect string `json:"effect"`
	// false — кнопку показать выключенной, причина — в disabled_reason
	Enabled bool `json:"enabled"`
	// Адрес действия в API
	Href string `json:"href"`
	// Подпись кнопки — показывать как есть
	Label string `json:"label"`
	// HTTP-метод действия
	Method string `json:"method"`
}

// ProposalActionAction — approve — «Записать и провести»; approve_draft — «Записать черновиком» (без проведения); reject — «Отклонить»
